<?php
namespace Tests\Feature;use App\Models\{User,Category,Product};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;class PurchaseTest extends TestCase{use RefreshDatabase;public function test_purchase_recalculates_total_and_decrements_stock():void{$u=User::factory()->create();$c=Category::create(['name'=>'Test','is_active'=>true]);$p=Product::create(['category_id'=>$c->id,'name'=>'Produit','description'=>'Test','price'=>1000,'stock'=>3,'is_active'=>true]);$this->actingAs($u)->postJson('/api/v1/purchases',['items'=>[['product_id'=>$p->id,'quantity'=>2]]])->assertCreated()->assertJsonPath('data.total','2000.00');$this->assertDatabaseHas('products',['id'=>$p->id,'stock'=>1]);}public function test_stock_cannot_be_negative():void{$u=User::factory()->create();$c=Category::create(['name'=>'Test','is_active'=>true]);$p=Product::create(['category_id'=>$c->id,'name'=>'Produit','description'=>'Test','price'=>1000,'stock'=>1,'is_active'=>true]);$this->actingAs($u)->postJson('/api/v1/purchases',['items'=>[['product_id'=>$p->id,'quantity'=>2]]])->assertStatus(409);}}
